  function loadPlot(v,base){const e=expectation(base.model,v.load/100),observed=e.rms+v.residual,xx=l=>78+(l-30)/70*620,yy=a=>288-a/6*235;let b=txt(78,25,'振动速度RMS / mm·s⁻¹；先比较同一负荷的正常期望');[0,1,2,3,4,5,6].forEach(a=>b+='<path d="M78 '+yy(a)+'H698" stroke="'+C.grid+'"/>'+txt(64,yy(a)+5,a,C.ink,'end'));[30,50,70,90,100].forEach(a=>b+=txt(xx(a),316,a,C.ink,'middle'));base.train.forEach(r=>b+='<circle cx="'+xx(r.load*100)+'" cy="'+yy(r.rms)+'" r="3.4" fill="'+C.blue+'" fill-opacity=".38"/>');const line=Array.from({length:71},(_,i)=>({load:30+i,rms:expectation(base.model,(30+i)/100).rms}));b+='<path d="'+line.map((r,i)=>(i?'L':'M')+xx(r.load)+','+yy(r.rms)).join(' ')+'" fill="none" stroke="'+C.blue+'" stroke-width="3"/><path d="M'+xx(v.load)+' '+yy(e.rms)+'V'+yy(observed)+'" stroke="'+C.red+'" stroke-width="4"/><circle cx="'+xx(v.load)+'" cy="'+yy(e.rms)+'" r="7" fill="'+C.paper+'" stroke="'+C.blue+'" stroke-width="2"/><circle cx="'+xx(v.load)+'" cy="'+yy(observed)+'" r="7" fill="'+C.red+'"/>'+txt(698,346,'额定负荷 / %',C.ink,'end')+txt(78,376,'蓝点：90条正常训练记录；蓝线：正常负荷回归',C.blue)+txt(78,403,'空心点：当前正常期望；红点：添加RMS残差后的观测',C.red);return{graphic:svg(b,420,'正常负荷与RMS关系散点及当前观测残差'),expectation:e,observed};}
