  function render(part,v,data){if(part==='background'){const r=loadPlot(v,data);return{graphic:r.graphic,text:'负荷'+v.load+'%时，正常期望RMS为'+f(r.expectation.rms)+' mm/s。添加'+f(v.residual)+' mm/s残差后，观测为'+f(r.observed)+' mm/s。只改变负荷时，红点和正常线一起移动，而红色竖线长度保持不变；这就是先解释负荷的作用。正常温度期望'+f(r.expectation.temperature,1)+'°C，峭度期望'+f(r.expectation.kurtosis)+'。',state:{inputs:v,expected:r.expectation,observedRMS:r.observed,residualRMS:v.residual,normalTrainingCount:90}};}const r=gatePlot(v,data),a32=r.spec.find(a=>a.hz===32).amplitude,a100=r.spec.find(a=>a.hz===100).amplitude;return{graphic:r.graphic,text:'第'+v.hour+'小时分数'+f(r.row.score)+'，验证阈值'+f(r.threshold)+'，已连续'+r.row.streak+'小时超阈值：'+(r.row.flag?'形成持续提醒。':'尚未形成持续提醒。')+'本段首次提醒'+(r.firstAlarm===null?'未出现':r.firstAlarm+' h')+'，共'+r.flagHours+' / 96小时满足规则。32 Hz幅值'+f(a32,3)+'，100 Hz幅值'+f(a100,3)+'；100 Hz成分由当前RMS正残差构造，沿32 Hz与100 Hz峰值比较负荷成分与残差成分。',state:{inputs:v,threshold:r.threshold,selectedObservation:{hour:r.row.hour,load:r.row.load,rms:r.row.rms,temperature:r.row.temperature,kurtosis:r.row.kurtosis,expected:r.row.expected,score:r.row.score,streak:r.row.streak,flag:r.row.flag},firstAlarm:r.firstAlarm,flagHours:r.flagHours,spectrum:r.spec}};}
